SELECT qryVAnolytElement.Elektrolyseur, qryVAnolytElement.Position, "El. "+[tblEingabeUnElement]![Elektrolyseur]+" Pos. "+Format([tblEingabeUnElement]![Position],"0") AS Bezeichnung, tblEingabeUnElement.Datum, tblEingabeUnElement.Zeit, qryVAnolytElement.VAnolyt, EtaNaClO3Ber([Analyse Anolyt Element]![NaClO3 An],[VAnolyt],[Analyse Pure Brine Element]![NaClO3 Pb],[Analyse Pure Brine Element]![flow rate],1,[tblEingabeUnElement]![I Gesamt]) AS µNaClO3, EtaNaOClBer([Analyse Anolyt Element]![NaOCl An],[VAnolyt],1,[tblEingabeUnElement]![I Gesamt]) AS µNaOCl, EtaAlkaliBer([Analyse Pure Brine Element]![NaOH Pb],[Analyse Pure Brine Element]![flow rate],1,[tblEingabeUnElement]![I Gesamt]) AS µAlkali, EtaNa2CO3Ber([Analyse Pure Brine Element]![Na2CO3 Pb],[Analyse Pure Brine Element]![flow rate],1,[tblEingabeUnElement]![I Gesamt]) AS µNa2CO3, EtaHClBer([Analyse Pure Brine Element]![HCl Pb],[Analyse Pure Brine Element]![flow rate],[Analyse Anolyt Element]![HCl An],[VAnolyt],1,[tblEingabeUnElement]![I Gesamt]) AS µHCl, EtaO2Ber([Analyse Chlorgas Element]![O2 Cl],[Analyse Chlorgas Element]![Cl2 + CO2 Cl],[µNaClO3],[µNaOCl]) AS µO2, EtaMembraneBer([µO2],[µNaClO3],[µNaOCl],[µHCl],[µNa2CO3],[µAlkali]) AS µNaOH, GEtGewAKF() AS CheckAKF, AktOClAnalyse() AS CheckClO, AktAnsaeurung() AS CheckAnsaeurung
FROM tblGewDaten, (((qryVAnolytElement INNER JOIN [Analyse Anolyt Element] ON (qryVAnolytElement.Datum = [Analyse Anolyt Element].Datum) AND (qryVAnolytElement.Position = [Analyse Anolyt Element].Position) AND (qryVAnolytElement.Elektrolyseur = [Analyse Anolyt Element].Elektrolyseur)) INNER JOIN [Analyse Chlorgas Element] ON ([Analyse Anolyt Element].Datum = [Analyse Chlorgas Element].Datum) AND ([Analyse Anolyt Element].Position = [Analyse Chlorgas Element].Position) AND ([Analyse Anolyt Element].Elektrolyseur = [Analyse Chlorgas Element].Elektrolyseur)) INNER JOIN [Analyse Pure Brine Element] ON ([Analyse Chlorgas Element].Datum = [Analyse Pure Brine Element].Datum) AND ([Analyse Chlorgas Element].Position = [Analyse Pure Brine Element].Position) AND ([Analyse Chlorgas Element].Elektrolyseur = [Analyse Pure Brine Element].Elektrolyseur)) INNER JOIN tblEingabeUnElement ON ([Analyse Pure Brine Element].Datum = tblEingabeUnElement.Datum) AND ([Analyse Pure Brine Element].Position = tblEingabeUnElement.Position) AND ([Analyse Pure Brine Element].Elektrolyseur = tblEingabeUnElement.Elektrolyseur)
WHERE (((tblEingabeUnElement.Datum)>=[tblGewDaten].[Anfangsdatum] And (tblEingabeUnElement.Datum)<=[tblGewDaten].[Enddatum]) AND ((qryVAnolytElement.VAnolyt)<>(-1)) AND ((EtaNaClO3Ber([Analyse Anolyt Element]![NaClO3 An],[VAnolyt],[Analyse Pure Brine Element]![NaClO3 Pb],[Analyse Pure Brine Element]![flow rate],1,[tblEingabeUnElement]![I Gesamt]))<>(-1)) AND ((EtaNaOClBer([Analyse Anolyt Element]![NaOCl An],[VAnolyt],1,[tblEingabeUnElement]![I Gesamt]))<>(-1)) AND ((EtaAlkaliBer([Analyse Pure Brine Element]![NaOH Pb],[Analyse Pure Brine Element]![flow rate],1,[tblEingabeUnElement]![I Gesamt]))<>(-1)) AND ((EtaNa2CO3Ber([Analyse Pure Brine Element]![Na2CO3 Pb],[Analyse Pure Brine Element]![flow rate],1,[tblEingabeUnElement]![I Gesamt]))<>(-1)) AND ((EtaHClBer([Analyse Pure Brine Element]![HCl Pb],[Analyse Pure Brine Element]![flow rate],[Analyse Anolyt Element]![HCl An],[VAnolyt],1,[tblEingabeUnElement]![I Gesamt]))<>(-1)))
ORDER BY tblEingabeUnElement.Datum;
